SET FOREIGN_KEY_CHECKS = 0;

-- ========================================================
-- 1. MEMBUAT DAN MENGISI TABEL BARANG
-- ========================================================
CREATE TABLE IF NOT EXISTS barang (
    id INT AUTO_INCREMENT PRIMARY KEY,
    nama_barang VARCHAR(255) NOT NULL,
    stok_minimum INT NOT NULL DEFAULT 10
);

TRUNCATE TABLE barang;

-- ========================================================
-- 2. MEMBUAT DAN MENGISI TABEL TRANING
-- ========================================================
CREATE TABLE IF NOT EXISTS traning (
    id INT AUTO_INCREMENT PRIMARY KEY,
    id_barang INT NOT NULL,
    tahun INT NOT NULL,
    bulan INT NOT NULL,
    persediaan_awal INT NOT NULL,
    pembelian INT NOT NULL,
    penjualan INT NOT NULL,
    persediaan_akhir INT NOT NULL,
    created_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    FOREIGN KEY (id_barang) REFERENCES barang(id) ON DELETE CASCADE
);

TRUNCATE TABLE traning;
SET FOREIGN_KEY_CHECKS = 1;